 dialog.Show();Application.DoEvents();if(!key.UseSystemPasswordChar)throw new Exception("Key must be masked");Field<Button>(dialog,"btnToggleKey").PerformClick();if(key.UseSystemPasswordChar)throw new Exception("Reveal key control");Field<Button>(dialog,"btnToggleKey").PerformClick();
 foreach(var size in new[]{new Size(600,610),new Size(760,720),new Size(560,520)}){dialog.ClientSize=size;Application.DoEvents();if(!prompt.Parent.Visible||prompt.Height<60)throw new Exception("Prompt edit area clipped");if(!dialog.ClientRectangle.Contains(Field<Button>(dialog,"btnSave").PointToScreen(Point.Empty)-new Size(dialog.PointToScreen(Point.Empty))))throw new Exception("Save outside window");}
